<script setup>
import {ref,computed,watch,onUnmounted} from 'vue'
import ReportText from './ReportText.vue'
const props=defineProps({base:String,taskId:String,entries:Array})
const emit=defineEmits(['changed','open-work','metrics'])
const binding=ref(null),context=ref(null),source=ref(null),metrics=ref(null),suites=ref([]),experiments=ref([]),error=ref(''),message=ref(''),busy=ref(false)
const observations=ref([]),compileMode=ref('MOCK')
const family=ref(''),contractKey=ref(''),roles=ref({}),fields=ref([]),baseEntry=ref(''),ruleTitle=ref(''),ruleKey=ref(''),cause=ref(''),failure=ref('OUTPUT_OMISSION'),scope=ref('TASK_CONTRACT'),target=ref(''),conditionPath=ref(''),suiteKey=ref(''),semantic=ref('HUMAN_REQUIRED'),policySlot=ref(''),policyValue=ref('REQUIRE'),actions=ref(''),supersedes=ref(false)
const chosenSuite=ref(''),chosenRule=ref(''),review=ref(null),judgments=ref({}),reviewNote=ref(''),relationSource=ref(''),relationTarget=ref(''),relationKind=ref('DERIVED_FROM'),relationNote=ref('')
const rules=computed(()=>(props.entries||[]).filter(e=>e.kind==='RULE' && !e.borrowed_read_only))
const candidates=computed(()=>rules.value.filter(e=>['PROPOSED','RETIRE'].includes(e.decision)))
const metricNames={applicable_recall:'적용 대상 회수율',rule_compliance:'규칙 준수율',regression_rate:'고정 사례 퇴행률',conflict_rate:'선택 규칙 충돌률'}
const roleNames={RESEARCH:'자료 수집',CALCULATE:'계산',INTERPRET:'해석',WRITE:'작성',REVIEW:'검토'}
const failureNames={FACT_ERROR:'사실 오류',PROCEDURE_ERROR:'절차 오류',OUTPUT_OMISSION:'출력 누락',REASONING_ERROR:'추론 오류',TECHNICAL_FAILURE:'기술적 실패'}
let sequence=0,timer,compilationSignature=''
async function get(path){const r=await fetch(props.base+path);if(!r.ok)throw Error((await r.json()).detail||'조회하지 못했습니다.');return r.json()}
async function post(path,body){const r=await fetch(props.base+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail));return data}
function flatten(value,path='',out=[]){if(out.length>=100)return out;if(value && typeof value==='object' && !Array.isArray(value)){for(const [key,v] of Object.entries(value))flatten(v,path+'/'+key.replaceAll('~','~0').replaceAll('/','~1'),out)}else if(path)out.push({path,type:Array.isArray(value)?'array':typeof value==='number'?'number':typeof value==='boolean'?'boolean':'string',selected:false,unit:'',meaning:''});return out}
async function load(){const id=props.taskId,seq=++sequence;try{const [b,c,s,m,ss,x,o]=await Promise.all([get(`/tasks/${id}/procedure-binding`),get(`/tasks/${id}/text-experiment-context`),get(`/tasks/${id}/text-source`),get(`/tasks/${id}/knowledge-metrics`),get(`/tasks/${id}/regression-suites`),get(`/tasks/${id}/text-experiments`),get(`/tasks/${id}/experience-observations`)]);if(seq!==sequence)return;const signature=o.flatMap(v=>v.compilations.map(t=>t.work_id+':'+t.status)).join('|');if(compilationSignature && signature!==compilationSignature)emit('changed');compilationSignature=signature;observations.value=o;binding.value=b;context.value=c;source.value=s;metrics.value=m;emit('metrics',m);suites.value=ss;experiments.value=x.filter(e=>e.result?.candidate_entry_id || e.knowledge_candidate_id);if(!chosenSuite.value)chosenSuite.value=ss[0]?.suite_id||'';if(!b){roles.value=Object.fromEntries(c.plan.steps.map((s,i)=>[s.id,i===c.plan.steps.length-1?'WRITE':'RESEARCH']));try{fields.value=flatten(JSON.parse(s.source_text))}catch{fields.value=[]}}}catch(e){if(seq===sequence)error.value=e.message}}
watch(()=>props.taskId,()=>{binding.value=null;context.value=null;error.value='';message.value='';review.value=null;chosenSuite.value='';chosenRule.value='';baseEntry.value='';load()},{immediate:true})
timer=setInterval(()=>{if(experiments.value.some(x=>x.status==='RUNNING') || observations.value.some(o=>o.compilations.some(x=>['CREATED','READY','RUNNING'].includes(x.status))))load()},4000)
onUnmounted(()=>{sequence++;clearInterval(timer)})
async function perform(action){busy.value=true;error.value='';message.value='';try{await action();await load();emit('changed')}catch(e){error.value=e.message}finally{busy.value=false}}
async function compileObservation(observation){await perform(async()=>{await post(`/experience-observations/${observation.observation_id}/compile`,{mode:compileMode.value,expected_binding_sha256:binding.value.binding_sha256,idempotency_key:crypto.randomUUID()});message.value='경험 분석 Work를 등록했습니다. 원인은 가설이고 결과는 미적용 후보입니다. 실제 실행과 실패는 이력에 남습니다.'})}
async function saveBinding(){await perform(async()=>{await post(`/tasks/${props.taskId}/procedure-binding`,{binding:{family:family.value,contract_key:contractKey.value,step_roles:roles.value,input_fields:Object.fromEntries(fields.value.filter(f=>f.selected).map(f=>[f.path,{type:f.type,unit:f.unit,meaning:f.meaning}]))},idempotency_key:crypto.randomUUID()});message.value='업무 유형·필드 의미를 고정했습니다. 데이터가 바뀌어도 이 계약에 맞는 절차만 재사용합니다.'})}
function startNormalization(){const entry=props.entries.find(e=>e.entry_id===baseEntry.value);ruleTitle.value=entry?.title||'';ruleKey.value='rule-'+crypto.randomUUID().slice(0,8);policySlot.value=ruleKey.value;cause.value='';target.value=context.value?.plan.steps.at(-1)?.id||'';actions.value=JSON.stringify([{kind:'REQUIRE_SECTION',action_id:'required-content',heading:'확인할 근거',instruction:entry?.payload?.text||'필요한 입력·근거·해석을 설명하세요.',required_components:[],input_paths:[]}],null,2)}
async function saveRule(){await perform(async()=>{const payload={rule_key:ruleKey.value,failure_mode:failure.value,root_cause:cause.value,scope:{kind:scope.value,binding_sha256:binding.value.binding_sha256,...(scope.value==='EXACT_INPUT'?{input_sha256:source.value.source_sha256}:{})},target_steps:[target.value],target_roles:[],when:conditionPath.value?[{path:'/source'+conditionPath.value,op:'EXISTS'}]:[],unless:[],actions:JSON.parse(actions.value),verification:{suite_key:suiteKey.value,severity:'BLOCK',semantic_review:semantic.value},policy_slot:policySlot.value,policy_value:policyValue.value};const body={title:ruleTitle.value,rule:payload,note:cause.value,idempotency_key:crypto.randomUUID()};const result=baseEntry.value?await post(`/knowledge/${baseEntry.value}/normalize`,body):await post(`/tasks/${props.taskId}/knowledge`,{kind:'RULE',title:ruleTitle.value,payload,idempotency_key:crypto.randomUUID()});if(supersedes.value && baseEntry.value)await post(`/knowledge/${result.entry_id}/relations`,{kind:'SUPERSEDES',target_entry_id:baseEntry.value,note:cause.value,idempotency_key:crypto.randomUUID()});chosenRule.value=result.entry_id;message.value='정규화 후보를 저장했습니다. 비교평가와 사용자 적용 전에는 실행에 사용하지 않습니다.'})}
async function compare(){await perform(async()=>{await post(`/tasks/${props.taskId}/text-experiments`,{suite_id:chosenSuite.value,candidate_revision:context.value.registered_revision,knowledge_candidate_id:chosenRule.value,idempotency_key:crypto.randomUUID()});message.value='같은 기초 기억·고정 입력으로 비교 실행을 등록했습니다. 후보 규칙만 Challenger에 추가됩니다.'})}
async function finish(id){await perform(()=>post(`/text-experiments/${id}/finish`,{idempotency_key:crypto.randomUUID()}))}
async function openReview(id){await perform(async()=>{review.value=await get(`/text-experiments/${id}/semantic-review`);judgments.value={};reviewNote.value=''})}
async function submitReview(){await perform(async()=>{await post(`/text-experiments/${review.value.experiment_id}/semantic-review`,{packet_sha256:review.value.packet_sha256,judgments:review.value.cases.map(c=>({case_id:c.case_id,preference:judgments.value[c.case_id]?.preference,critical_labels:judgments.value[c.case_id]?.critical||[],note:judgments.value[c.case_id]?.note||''})),note:reviewNote.value,idempotency_key:crypto.randomUUID()});message.value='사용자 판단을 기록했습니다. 규칙 적용은 별도의 명시적 결정입니다.';review.value=null})}
function preference(id,value){judgments.value[id]??={preference:'',critical:[],note:''};judgments.value[id].preference=value}
async function saveRelation(){await perform(async()=>{await post(`/knowledge/${relationSource.value}/relations`,{target_entry_id:relationTarget.value,kind:relationKind.value,note:relationNote.value,idempotency_key:crypto.randomUUID()});message.value='관계를 기록했습니다. 원본 지식과 실행 이력은 보존합니다.'})}
const reviewReady=computed(()=>review.value && reviewNote.value.trim() && review.value.cases.every(c=>judgments.value[c.case_id]?.preference && judgments.value[c.case_id]?.note?.trim()))
defineExpose({load})
</script>

<template>
  <section class="experience-workbench" aria-label="경험을 실행 규칙으로">
    <header><small>EXPERIENCE / EVIDENCE / PROCEDURE</small><h3>경험을 다음 작업의 절차로</h3><p>원문 보존 → 조건·행동 정규화 → 같은 입력의 비교 → 검토 후 적용</p></header>
    <p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="message" role="status">{{ message }}</p>
    <p v-if="!context">등록된 텍스트 업무에서 절차 규칙을 구성할 수 있습니다. 기존 데모의 결정론적 업무는 해당 검증 경로를 유지합니다.</p>
    <template v-if="context">
      <p class="mode">{{ context.model_mode==='LIVE_LLM'?'LIVE LLM · 사용자 제공 자료':'MOCK · 모델 품질 실험 아님' }} · 미검토 의견은 실행 규칙이 아닙니다.</p>
      <div v-if="metrics" class="metric-strip"><div v-for="(metric,key) in metrics.metrics" :key="key"><span>{{ metricNames[key] }}</span><strong>{{ metric.value===null?'자료 없음':(metric.value*100).toFixed(1)+'%' }}</strong><small>{{ metric.numerator }} / {{ metric.denominator }}</small></div></div>
      <p class="caption">회수율은 별도 사용자 정답이 있는 실행만, 준수율은 설정한 검사만 집계합니다. 퇴행률·효용은 같은 고정 사례의 비교이며 전 회차 점수차가 아닙니다.</p>
      <details><summary>1. 재사용할 업무 범위와 필드 의미</summary>
        <template v-if="binding"><p><b>{{ binding.binding.family }}</b> · {{ binding.binding.contract_key }}</p><p>데이터 값이 바뀌어도 필드의 의미·단위와 단계 계약이 같을 때만 절차를 재사용합니다. 직접 인용과 개별 사실에는 적용하지 않습니다.</p><dl><template v-for="(field,path) in binding.binding.input_fields" :key="path"><dt>{{ path }}</dt><dd>{{ field.meaning }} · {{ field.unit }} · {{ field.type }}</dd></template></dl></template>
        <template v-else><label>업무 유형<input v-model="family" placeholder="예: household_report"></label><label>절차 계약 이름<input v-model="contractKey" placeholder="예: fixed-basket-v1"></label><div class="form-grid"><label v-for="step in context.plan.steps" :key="step.id">{{ step.title }}<select v-model="roles[step.id]"><option v-for="(name,key) in roleNames" :key="key" :value="key">{{ name }}</option></select></label></div><p>재사용 규칙이 의존하는 입력 필드를 선택하고 실제 의미·단위를 명시하세요.</p><div v-for="field in fields" :key="field.path" class="field-row"><label class="checkbox"><input type="checkbox" v-model="field.selected">{{ field.path }} · {{ field.type }}</label><template v-if="field.selected"><input v-model="field.meaning" aria-label="필드 의미" placeholder="예: 식품 기준지출"><input v-model="field.unit" aria-label="필드 단위" placeholder="예: KRW, percent"></template></div><button @click="saveBinding" :disabled="busy || !family.trim() || !contractKey.trim() || fields.some(f=>f.selected && (!f.unit.trim() || !f.meaning.trim()))">범위를 명시해 고정</button></template>
      </details>
      <details v-if="binding"><summary>관찰한 경험에서 원인·규칙 후보 제안</summary><p>분류와 원인은 검토할 가설입니다. 분석은 기존 큐의 별도 Work/Run으로 실행하고, 원문 인용·형식 검사를 통과해도 규칙은 미적용 후보로 남습니다.</p><label>분석 방식<select v-model="compileMode"><option value="MOCK">MOCK · 경로 시연, 실제 원인 분석 아님</option><option value="LIVE_LLM">LIVE LLM · 현재 모델로 근거와 원인 가설 분석</option></select></label><p v-if="compileMode==='LIVE_LLM'">보고서·원 입력·피드백과 현재 절차 계약을 설정한 모델로 전달합니다. 추가 웹 검색은 하지 않습니다.</p><article v-for="observation in observations.slice(0,8)" :key="observation.observation_id"><b>{{ failureNames[observation.classification] || '분류 검토 필요' }} · 미확정</b><p>{{ observation.snapshot.note }}</p><button class="secondary" @click="compileObservation(observation)" :disabled="busy || observation.compilations.some(c=>['CREATED','READY','RUNNING'].includes(c.status))">원인 가설·실행 규칙 후보 분석</button><button v-for="compilation in observation.compilations" :key="compilation.work_id" class="secondary" @click="emit('open-work',compilation.work_id,compilation.run_id)">{{ compilation.model_mode }} · 분석 {{ compilation.run_status || compilation.status }}</button></article><p v-if="!observations.length">이 태스크에 기록된 경험 관찰이 아직 없습니다.</p></details>
      <details v-if="binding"><summary>2. 교훈을 실행·검사 가능한 후보로 정규화</summary>
        <label>원본 지식<select v-model="baseEntry" @change="startNormalization"><option value="">직접 작성한 절차</option><option v-for="entry in entries.filter(e=>!e.borrowed_read_only)" :key="entry.entry_id" :value="entry.entry_id">{{ entry.title }} · {{ entry.kind }}</option></select></label><button class="secondary" @click="startNormalization">후보 작성 시작</button>
        <template v-if="ruleKey"><div class="form-grid"><label>독자·검토자용 제목<input v-model="ruleTitle" maxlength="150"></label><label>규칙 식별 이름<input v-model="ruleKey"></label><label>관찰한 문제<select v-model="failure"><option v-for="(name,key) in failureNames" :key="key" :value="key">{{ name }}</option></select></label><label>적용할 단계<select v-model="target"><option v-for="step in context.plan.steps" :key="step.id" :value="step.id">{{ step.title }}</option></select></label><label>적용 범위<select v-model="scope"><option value="TASK_CONTRACT">같은 태스크의 호환 계약</option><option value="INPUT_SCHEMA">같은 의미·단위의 입력 스키마</option><option value="TASK_FAMILY">명시적으로 연결한 업무 유형</option><option value="EXACT_INPUT">정확히 이 입력에만</option></select></label><label>이 필드가 있을 때<select v-model="conditionPath"><option value="">해당 단계에서 항상</option><option v-for="(field,path) in binding.binding.input_fields" :key="path" :value="path">{{ field.meaning }}</option></select></label></div>
          <label>실패 원인·정정 근거<textarea v-model="cause" rows="3" placeholder="단순 평가 의견이 아니라 확인한 원인과 제외해야 할 상황을 적으세요."></textarea></label>
          <details><summary>행동 설정 · 제한된 JSON 계약</summary><p>REQUIRE_SECTION, CALCULATE, PRECONDITION, CHECK_CLAIMS를 지원합니다. 산식·입력·해석이 필요하면 required_components와 검산할 formula/input_paths를 지정하세요. 코드나 SQL은 실행하지 않습니다.</p><textarea v-model="actions" rows="12" class="code" aria-label="규칙 행동 JSON"></textarea></details>
          <div class="form-grid"><label>고정 평가 검사 이름<input v-model="suiteKey" placeholder="평가 사례의 suite_key와 같게"></label><label>의미 검토<select v-model="semantic"><option value="HUMAN_REQUIRED">실제 사용자 판단 필요</option><option value="DOMAIN_ASSERTIONS">구조화된 도메인 대조 범위만</option></select></label><label>충돌 확인 주제<input v-model="policySlot"></label><label>이 주제의 정책값<input v-model="policyValue" placeholder="예: REQUIRE"></label></div>
          <label v-if="baseEntry" class="checkbox"><input type="checkbox" v-model="supersedes">기존 규칙의 정정·대체 후보로 연결</label><button @click="saveRule" :disabled="busy || !ruleTitle.trim() || !cause.trim() || !suiteKey.trim() || !actions.trim()">원본을 보존하고 후보로 저장</button>
        </template>
      </details>
      <details v-if="binding"><summary>3. 같은 입력에서 후보 규칙의 효과 비교</summary><p>평가 사례에는 후보와 별도로 정한 도메인 검사와 보류 입력이 필요합니다. Work 상세의 회귀 사례 등록에서 만들고 고정하세요. 기준군에도 같은 기초 기억을 고정합니다.</p><label>규칙 후보<select v-model="chosenRule"><option value="">선택</option><option v-for="rule in candidates" :key="rule.entry_id" :value="rule.entry_id">{{ rule.title }}</option></select></label><label>고정 평가셋<select v-model="chosenSuite"><option value="">선택</option><option v-for="suite in suites" :key="suite.suite_id" :value="suite.suite_id">평가 v{{ suite.version }} · {{ suite.snapshot.cases.length }}개 사례</option></select></label><button @click="compare" :disabled="busy || !chosenRule || !chosenSuite || context.latest_revision!==context.registered_revision">후보 규칙만 바꿔 비교 실행</button><p v-if="context.latest_revision!==context.registered_revision">아직 등록되지 않은 작업 설계 변경이 있습니다. 이번 비교에서 절차와 지식이 함께 바뀌지 않도록 먼저 정리하세요.</p></details>
      <article v-for="experiment in experiments" :key="experiment.experiment_id" class="comparison"><h4>규칙 비교 · {{ experiment.status==='RUNNING'?'실행 중':experiment.verdict==='PASS'?'설정한 비교 검사 통과':'비교 검사 미통과' }}</h4><p v-if="experiment.result">기준 {{ experiment.result.champion_passed }}/{{ experiment.result.case_count }} → 후보 {{ experiment.result.challenger_passed }}/{{ experiment.result.case_count }} · 퇴행 {{ experiment.result.regressions.length }}건</p><p v-if="experiment.result" class="caption">구조화된 도메인 검사 결과입니다. 자유 문장 전체의 의미·전문가 품질을 보증하지 않습니다. 적용은 아래 지식 카드에서 결정합니다.</p><div class="actions"><button v-if="experiment.status==='RUNNING'" @click="finish(experiment.experiment_id)" :disabled="busy || experiment.runs.some(r=>!r.run_status || r.run_status==='RUNNING')">실행 결과 집계</button><button v-else class="secondary" @click="openReview(experiment.experiment_id)" :disabled="busy || experiment.runs.some(r=>r.run_status!=='SUCCEEDED')">방법 이름을 숨기고 직접 비교</button><button v-for="run in experiment.runs" :key="run.work_id" class="secondary" @click="emit('open-work',run.work_id,run.run_id)">{{ run.side==='CHAMPION'?'기준':'후보' }} 실행 {{ run.run_status || '대기' }}</button></div></article>
      <section v-if="review" class="human-review"><h4>실제 사용자 비교 판단</h4><p>{{ review.instructions }}</p><article v-for="item in review.cases" :key="item.case_id"><details><summary>이 사례의 입력·기대 행동</summary><pre>{{ item.source_text }}</pre><p>{{ item.expected_behavior }}</p></details><div class="pair"><div v-for="label in ['A','B']" :key="label"><b>출력 {{ label }}</b><ReportText :text="item.outputs[label].text" /></div></div><div class="actions"><button v-for="choice in ['A','B','TIE','NEITHER']" :key="choice" :class="judgments[item.case_id]?.preference===choice?'chosen':'secondary'" @click="preference(item.case_id,choice)">{{ {A:'A가 더 유용',B:'B가 더 유용',TIE:'동등함',NEITHER:'둘 다 부적절'}[choice] }}</button></div><label v-if="judgments[item.case_id]">판단 근거<textarea v-model="judgments[item.case_id].note" rows="2"></textarea></label></article><label>전체 검토 사유<textarea v-model="reviewNote" rows="2"></textarea></label><button @click="submitReview" :disabled="busy || !reviewReady">내 판단을 기록 · 규칙은 자동 적용하지 않음</button></section>
      <details><summary>4. 중복·충돌·정정 관계와 유지보수</summary><ul v-if="metrics?.suggestions.length"><li v-for="(suggestion,i) in metrics.suggestions.slice(0,12)" :key="i">{{ entries.find(e=>e.entry_id===suggestion.entry_id)?.title || suggestion.entry_id }} — {{ suggestion.reason }}</li></ul><p v-else>현재 근거로 제안할 유지보수 항목이 없습니다. 효용을 확인하지 못했다는 뜻과 구분하세요.</p><label>관계를 기록할 지식<select v-model="relationSource"><option value="">선택</option><option v-for="entry in entries.filter(e=>!e.borrowed_read_only)" :key="entry.entry_id" :value="entry.entry_id">{{ entry.title }}</option></select></label><label>관계<select v-model="relationKind"><option value="DERIVED_FROM">근거에서 파생</option><option value="DUPLICATE_OF">기존 항목과 중복 · 근거 연결</option><option value="CONFLICTS_WITH">동시에 적용할 수 없는 충돌</option><option value="SUPERSEDES">이전 항목 정정·대체</option><option value="ENRICHES">기존 항목 보완 근거</option></select></label><label>연결 대상<select v-model="relationTarget"><option value="">선택</option><option v-for="entry in entries.filter(e=>!e.borrowed_read_only && e.entry_id!==relationSource)" :key="entry.entry_id" :value="entry.entry_id">{{ entry.title }}</option></select></label><label>확인한 근거<textarea v-model="relationNote" rows="2"></textarea></label><button @click="saveRelation" :disabled="busy || !relationSource || !relationTarget || !relationNote.trim()">관계만 기록 · 원본 보존</button></details>
    </template>
  </section>
</template>

