51}.human-review{padding:18px;background:#e9efdf}.human-review article{padding-bottom:18px;border-bottom:1px solid #bfccb2}dl{display:grid;grid-template-columns:minmax(80px,1fr) 2fr;gap:8px}dt{font:11px Consolas,monospace}dd{margin:0}@media(max-width:800px){.metric-strip{grid-template-columns:1fr 1fr}.form-grid,.pair{grid-template-columns:1fr}.metric-strip>div:nth-child(2){border-right:0}}
